import { createCipheriv, createDecipheriv, randomBytes } from 'crypto';

// Đảm bảo Confidentiality (Mã hóa AES-256-GCM) và Integrity (Auth Tag chống giả mạo)
export class DataSecurityVault {
  private static readonly ALGORITHM = 'aes-256-gcm';
  private static readonly KEY = Buffer.from(process.env.DATA_VAULT_KEY || '', 'hex'); // 32 bytes

  static encrypt(plaintext: string): { ciphertext: string; iv: string; authTag: string } {
    const iv = randomBytes(12); // GCM standard IV: 96-bit (12 bytes)
    const cipher = createCipheriv(this.ALGORITHM, this.KEY, iv);

    let encrypted = cipher.update(plaintext, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    const authTag = cipher.getAuthTag().toString('hex'); // Đảm bảo Integrity

    return { ciphertext: encrypted, iv: iv.toString('hex'), authTag };
  }

  static decrypt(ciphertext: string, ivHex: string, authTagHex: string): string {
    const decipher = createDecipheriv(this.ALGORITHM, this.KEY, Buffer.from(ivHex, 'hex'));
    decipher.setAuthTag(Buffer.from(authTagHex, 'hex')); // Xác minh tính toàn vẹn (Integrity)

    let decrypted = decipher.update(ciphertext, 'hex', 'utf8');
    decrypted += decipher.final('utf8'); // Sẽ ném lỗi nếu ciphertext bị chỉnh sửa dù 1 bit
    return decrypted;
  }
}

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

export interface AuthenticatedUser {
  id: string;
  tenantId: string;
  roles: string[];
}

export interface AuthRequest extends Request {
  user?: AuthenticatedUser;
}

// 1. Authentication Middleware: Bạn là ai? (Identity Verification)
export const authenticateJWT = (req: AuthRequest, res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: '401 Unauthorized: Thiếu token hoặc định dạng không hợp lệ' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_PUBLIC_KEY!, { algorithms: ['RS256'] }) as AuthenticatedUser;
    req.user = decoded; // Danh tính được xác thực thành công
    next();
  } catch (err) {
    return res.status(401).json({ error: '401 Unauthorized: Token hết hạn hoặc chữ ký không hợp lệ' });
  }
};

// 2. Authorization Middleware: Bạn có quyền làm hành động này không? (Access Control)
export const requireRoles = (...allowedRoles: string[]) => {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Chưa thực hiện authentication' });
    }
    const hasRole = req.user.roles.some(role => allowedRoles.includes(role));
    if (!hasRole) {
      return res.status(403).json({ error: '403 Forbidden: Không đủ quyền hạn truy cập tài nguyên này' });
    }
    next();
  };
};

import DOMPurify from 'isomorphic-dompurify';

// 1. Phân biệt các loại XSS:
// - Stored XSS: Mã độc lưu vĩnh viễn trong Database (ví dụ comment, profile bio). Mọi user đọc đều bị tấn công.
// - Reflected XSS: Mã độc nằm trong URL query params, server phản hồi lại nội dung đó vào HTML mà không escape.
// - DOM XSS: Mã độc hoàn toàn ở client-side, do JavaScript thao tác không an toàn (location.hash -> innerHTML).

// 2. Phòng thủ nhiều lớp (Defense in Depth)

// Lớp 1: Context-aware HTML sanitization khi bắt buộc phải render HTML
export function sanitizeUserHtml(dirtyHtml: string): string {
  return DOMPurify.sanitize(dirtyHtml, {
    ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a', 'p'],
    ALLOWED_ATTR: ['href', 'target'],
    ALLOW_DATA_ATTR: false
  });
}

// Lớp 2: Luôn encode text an toàn khi chèn vào DOM (tránh dùng element.innerHTML)
export function renderSafeText(container: HTMLElement, userInput: string): void {
  // ✅ AN TOÀN: textContent tự động escape HTML entities (<, >, &, ", ')
  container.textContent = userInput;
  // ❌ NGUY HIỂM: container.innerHTML = userInput; // Dẫn tới DOM-based XSS
}

import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';

const app = express();

// 1. Cấu hình Cookie an toàn với thuộc tính SameSite
export const sessionCookieConfig = {
  httpOnly: true,                               // Chống đọc qua XSS
  secure: process.env.NODE_ENV === 'production', // Chỉ gửi qua HTTPS
  sameSite: 'lax' as const,                     // Ngăn chặn hầu hết cross-site POST requests
  maxAge: 3600000
};

// 2. Triển khai Anti-CSRF Token (Double Submit Cookie Pattern hoặc Synchronizer Token)
export const csrfProtection = (req: Request, res: Response, next: NextFunction) => {
  // Các phương thức an toàn (Safe Methods) không làm thay đổi trạng thái
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) {
    return next();
  }

  const clientCsrfToken = req.headers['x-csrf-token'] || req.body?._csrf;
  const cookieCsrfToken = req.cookies?.['csrf-token'];

  if (!clientCsrfToken || !cookieCsrfToken || clientCsrfToken !== cookieCsrfToken) {
    return res.status(403).json({ error: 'CSRF Token missing or mismatch' });
  }

  next();
};

import { Pool } from 'pg';

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

export class UserRepository {
  // ❌ NGUY HIỂM CHẾT NGƯỜI: String concatenation dẫn tới SQL Injection
  // Input: "admin' --" hoặc "' OR 1=1 --"
  static async vulnerableSearch(username: string) {
    const rawQuery = `SELECT id, username, email FROM users WHERE username = '${username}'`;
    return await pool.query(rawQuery); // Kẻ tấn công đọc toàn bộ DB hoặc bypass login
  }

  // ✅ AN TOÀN TUYỆT ĐỐI: Parameterized Query (Prepared Statement)
  static async secureSearch(username: string) {
    const query = `
      SELECT id, username, email, created_at 
      FROM users 
      WHERE username = $1 
      LIMIT 10
    `;
    // DB engine biên dịch cú pháp SQL trước, biến $1 chỉ được coi là literal value (dữ liệu thô)
    const result = await pool.query(query, [username]);
    return result.rows;
  }
}

import argon2 from 'argon2';

export class PasswordSecurity {
  // Argon2id là thuật toán thắng giải Password Hashing Competition (PHC)
  // Kết hợp chống Side-channel timing attack (Argon2i) và GPU brute-force (Argon2d)
  private static readonly OPTIONS: argon2.Options = {
    type: argon2.argon2id,
    memoryCost: 65536, // 64 MB RAM (Memory-hard: chống ASIC và GPU farms)
    timeCost: 3,       // 3 iterations
    parallelism: 2,    // 2 threads
    saltLength: 16     // 16 bytes cryptographic random salt
  };

  static async hashPassword(password: string): Promise<string> {
    // Tự động sinh Salt ngẫu nhiên và nhúng kèm cấu hình vào output string
    return await argon2.hash(password, this.OPTIONS);
  }

  static async verifyPassword(hash: string, plainTextAttempt: string): Promise<boolean> {
    try {
      // Thực hiện constant-time comparison bên dưới để chống timing attack
      return await argon2.verify(hash, plainTextAttempt);
    } catch {
      return false;
    }
  }
}

import express, { Request, Response, NextFunction } from 'express';
import helmet from 'helmet';
import crypto from 'crypto';

const app = express();

// Middleware sinh Cryptographic Nonce độc nhất cho mỗi request
app.use((req: Request, res: Response, next: NextFunction) => {
  res.locals.cspNonce = crypto.randomBytes(16).toString('base64');
  next();
});

// Cấu hình Strict CSP qua Helmet
app.use((req: Request, res: Response, next: NextFunction) => {
  const nonce = res.locals.cspNonce;

  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      // Chỉ cho phép script có đúng Nonce được sinh từ server cho request này
      scriptSrc: ["'self'", `'nonce-${nonce}'`, "'strict-dynamic'"],
      styleSrc: ["'self'", `'nonce-${nonce}'`],
      imgSrc: ["'self'", 'data:', 'https://images.mycdn.com'],
      connectSrc: ["'self'", 'https://api.mycompany.com'],
      objectSrc: ["'none'"],       // Chặn Flash, Java Applets
      baseUri: ["'self'"],         // Chặn tấn công Base Tag Injection
      frameAncestors: ["'none'"],  // Chống Clickjacking
    },
  })(req, res, next);
});

// Render template HTML đính kèm nonce vào thẻ script
app.get('/', (req: Request, res: Response) => {
  const nonce = res.locals.cspNonce;
  res.send(`
    <!DOCTYPE html>
    <html>
      <head><title>Secure Page</title></head>
      <body>
        <h1>Production Application</h1>
        <!-- Script này hợp lệ và được chạy -->
        <script nonce="${nonce}">
          console.log("Internal script executed securely with nonce");
        </script>
        <!-- Payload XSS của hacker (không có nonce hợp lệ) sẽ bị browser block ngay lập tức -->
      </body>
    </html>
  `);
});

import express from 'express';
import cors from 'cors';

const app = express();

// Whitelist các origin được phép gọi API
const allowedOrigins = [
  'https://app.company.com',
  'https://admin.company.com'
];

export const corsOptions: cors.CorsOptions = {
  origin: (origin, callback) => {
    // Cho phép server-to-server requests hoặc non-browser clients (origin is undefined)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS Error: Origin không nằm trong danh sách cho phép'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true, // Cho phép truyền cookie hoặc Authorization header
  maxAge: 86400      // Cache preflight OPTIONS request trong 24h để giảm latency
};

// ❌ TUYỆT ĐỐI KHÔNG DÙNG: origin: '*' kết hợp credentials: true (Browser sẽ block vì vi phạm bảo mật)
app.use(cors(corsOptions));

import dns from 'dns/promises';
import ipaddr from 'ipaddr.js';
import axios from 'axios';

// Hàm kiểm tra an toàn URL trước khi fetch để chặn SSRF
export async function safeFetchUrl(inputUrl: string): Promise<Buffer> {
  const parsed = new URL(inputUrl);

  // 1. Chỉ cho phép giao thức HTTP/HTTPS (chặn file:///, gopher://, dict://)
  if (!['http:', 'https:'].includes(parsed.protocol)) {
    throw new Error('Giao thức không được phép');
  }

  // 2. Phân giải DNS ra IP để kiểm tra trước
  const records = await dns.lookup(parsed.hostname, { all: true });
  if (records.length === 0) throw new Error('Không phân giải được tên miền');

  for (const record of records) {
    const addr = ipaddr.parse(record.address);
    const range = addr.range();

    // 3. Chặn toàn bộ IP Private, Loopback, Link-Local (AWS IMDS: 169.254.169.254)
    const dangerousRanges = ['loopback', 'private', 'linkLocal', 'uniqueLocal', 'broadcast'];
    if (dangerousRanges.includes(range)) {
      throw new Error(`Phát hiện SSRF: IP ${record.address} thuộc dải cấm (${range})`);
    }
  }

  // 4. Fetch với timeout và giới hạn dung lượng tải về, tắt tự động follow redirects
  const response = await axios.get(inputUrl, {
    timeout: 3000,
    maxRedirects: 0, // Chặn bypass qua 302 Redirect về IP nội bộ
    responseType: 'arraybuffer',
    maxContentLength: 5 * 1024 * 1024 // Tối đa 5MB
  });

  return Buffer.from(response.data);
}

import { Request, Response } from 'express';
