interface Order {
  id: string;
  userId: string;
  tenantId: string;
  amount: number;
}

export class OrderService {
  // ❌ SAI LẦM PHỔ BIẾN: Chỉ tìm theo ID mà không quan tâm ai đang gửi request (Dẫn tới IDOR/BOLA)
  static async vulnerableGetOrder(orderId: string): Promise<Order | null> {
    return await db.orders.findUnique({ where: { id: orderId } });
  }

  // ✅ CHUẨN SẢN XUẤT: Luôn kèm Context của Current User (Data Ownership Verification)
  static async secureGetOrder(orderId: string, currentUserId: string, currentTenantId: string): Promise<Order> {
    const order = await db.orders.findFirst({
      where: {
        id: orderId,
        tenantId: currentTenantId, // Đảm bảo cô lập multi-tenant
        userId: currentUserId      // Chỉ chủ sở hữu mới đọc được
      }
    });

    if (!order) {
      // Trả về 404 thay vì 403 để tránh rò rỉ sự tồn tại của orderId (Data Enumeration)
      throw new Error('ORDER_NOT_FOUND');
    }

    return order;
  }
}

// Controller xử lý an toàn
export const getOrderDetailController = async (req: AuthRequest, res: Response) => {
  try {
    const { orderId } = req.params;
    const currentUser = req.user!; // Lấy từ token đã qua Authentication

    const order = await OrderService.secureGetOrder(orderId, currentUser.id, currentUser.tenantId);
    return res.json(order);
  } catch (err: any) {
    if (err.message === 'ORDER_NOT_FOUND') {
      return res.status(404).json({ error: 'Không tìm thấy đơn hàng' });
    }
    return res.status(500).json({ error: 'Internal server error' });
  }
};

import { SecretsManagerClient, GetSecretValueCommand } from '@aws-sdk/client-secrets-manager';

export class SecretConfigManager {
  private static client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'ap-southeast-1' });
  private static cachedSecrets: Record<string, string> = {};
  private static lastFetchTime = 0;
  private static readonly TTL_MS = 5 * 60 * 1000; // Cache 5 phút để hỗ trợ Auto-Rotation mà không spam AWS API

  static async getDatabaseSecret(): Promise<{ username: string; password: string; host: string }> {
    const now = Date.now();
    const secretName = process.env.DB_SECRET_NAME || 'prod/app/db-credentials';

    if (this.cachedSecrets[secretName] && (now - this.lastFetchTime < this.TTL_MS)) {
      return JSON.parse(this.cachedSecrets[secretName]);
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      if (!response.SecretString) {
        throw new Error('Secret không chứa dữ liệu dạng chuỗi');
      }

      this.cachedSecrets[secretName] = response.SecretString;
      this.lastFetchTime = now;

      return JSON.parse(response.SecretString);
    } catch (error) {
      console.error('Không thể lấy secret từ AWS Secrets Manager:', error);
      throw error;
    }
  }
}

import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

// Minh họa phòng chống Rủi ro #3: Broken Object Property Level Authorization (Mass Assignment)
interface UserProfileUpdateDTO {
  displayName?: string;
  avatarUrl?: string;
  // ❌ Kẻ tấn công cố tình chèn role: 'admin' hoặc isVip: true vào request body
}

app.patch('/api/users/profile', async (req: Request, res: Response) => {
  const { id: currentUserId } = (req as any).user;
  const rawBody = req.body;

  // ❌ NGUY HIỂM (Mass Assignment): db.users.update({ where: { id }, data: rawBody })

  // ✅ PHÒNG THỦ: Data Transfer Object (DTO) Whitelisting - Chỉ bóc tách các trường hợp lệ
  const safeUpdateData: UserProfileUpdateDTO = {
    displayName: typeof rawBody.displayName === 'string' ? rawBody.displayName : undefined,
    avatarUrl: typeof rawBody.avatarUrl === 'string' ? rawBody.avatarUrl : undefined
  };

  // Loại bỏ các trường undefined
  Object.keys(safeUpdateData).forEach(
    key => (safeUpdateData as any)[key] === undefined && delete (safeUpdateData as any)[key]
  );

  const updatedUser = await db.users.update({
    where: { id: currentUserId },
    data: safeUpdateData
  });

  return res.json({ success: true, data: updatedUser });
});

import jwt from 'jsonwebtoken';

// 1. Tuyệt đối KHÔNG lưu PII hay Secret trong Payload (Payload chỉ được Base64Url encode, KHÔNG mã hóa!)
export interface SafeJwtPayload {
  sub: string;     // User ID
  tenantId: string;
  roles: string[];
  iss: string;     // Issuer
  aud: string;     // Audience
}

// 2. Xác thực JWT an toàn: Chống thuật toán 'none' và 'Algorithm Confusion attack'
export function verifyJwtSecurely(token: string): SafeJwtPayload {
  const publicKey = process.env.JWT_RSA_PUBLIC_KEY!;

  return jwt.verify(token, publicKey, {
    // BẮT BUỘC: Khóa cứng danh sách thuật toán được phép (chặn hacker đổi sang 'none' hoặc 'HS256')
    algorithms: ['RS256'],
    issuer: 'https://auth.mycompany.com',
    audience: 'https://api.mycompany.com',
    clockTolerance: 5 // Cho phép lệch tối đa 5 giây
  }) as SafeJwtPayload;
}

import Redis from 'ioredis';
import { Request, Response, NextFunction } from 'express';

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

export class LoginRateLimiter {
  // Rate limiting theo IP và theo Email để chống cả brute-force đơn lẻ lẫn botnet phân tán
  static async checkAttempt(ip: string, email: string): Promise<{ allowed: boolean; remainingAttempts: number }> {
    const ipKey = `rate:login:ip:${ip}`;
    const accountLockKey = `lock:account:${email.toLowerCase()}`;

    // 1. Kiểm tra tài khoản có đang bị tạm khóa (Account Lockout) không
    const isLocked = await redis.get(accountLockKey);
    if (isLocked) {
      return { allowed: false, remainingAttempts: 0 };
    }

    // 2. Sliding window hoặc Fixed window limit: tối đa 5 lần thử sai trong 15 phút
    const attempts = await redis.incr(ipKey);
    if (attempts === 1) {
      await redis.expire(ipKey, 900); // 15 phút
    }

    if (attempts > 5) {
      return { allowed: false, remainingAttempts: 0 };
    }

    return { allowed: true, remainingAttempts: 5 - attempts };
  }

  // Khi login sai nhiều lần, kích hoạt progressive delay hoặc khóa tạm thời
  static async recordFailedAttempt(email: string) {
    const failKey = `fail:login:${email.toLowerCase()}`;
    const fails = await redis.incr(failKey);
    if (fails === 1) await redis.expire(failKey, 900);

    if (fails >= 5) {
      // Khóa tài khoản tạm thời 30 phút, đồng thời kích hoạt gửi email cảnh báo cho chủ tài khoản
      await redis.set(`lock:account:${email.toLowerCase()}`, '1', 'EX', 1800);
      console.warn(`Tài khoản ${email} đã bị tạm khóa 30 phút do login sai quá 5 lần`);
    }
  }
}

