import crypto from 'crypto';

export class OAuthPKCEHelper {
  // 1. Tạo ngẫu nhiên một Code Verifier có độ entropy cao (43 - 128 ký tự base64url)
  static generateCodeVerifier(): string {
    return crypto.randomBytes(32)
      .toString('base64url'); // Tự động format URL-safe không có +, /, =
  }

  // 2. Tạo Code Challenge bằng thuật toán S256: BASE64URL-ENCODE(SHA256(CodeVerifier))
  static generateCodeChallenge(codeVerifier: string): string {
    return crypto.createHash('sha256')
      .update(codeVerifier)
      .digest('base64url');
  }

  // 3. Khởi tạo URL chuyển hướng đến Authorization Server
  static buildAuthorizeUrl(codeChallenge: string): string {
    const authEndpoint = 'https://auth.company.com/oauth/authorize';
    const params = new URLSearchParams({
      response_type: 'code',
      client_id: 'mobile-app-client-id', // Public Client: không có client_secret!
      redirect_uri: 'com.company.app://oauth/callback',
      scope: 'openid profile email',
      code_challenge: codeChallenge,
      code_challenge_method: 'S256',     // Bắt buộc S256, cấm dùng 'plain'
      state: crypto.randomBytes(16).toString('hex') // Chống CSRF
    });

    return `${authEndpoint}?${params.toString()}`;
  }
}

import https from 'https';
import fs from 'fs';
import express from 'express';

// Triển khai Server mTLS (Mutual TLS): Xác thực danh tính 2 chiều bằng chứng chỉ X.509
export function createMtlsServer() {
  const app = express();

  const options: https.ServerOptions = {
    key: fs.readFileSync('/etc/certs/service-key.pem'),   // Private key của server
    cert: fs.readFileSync('/etc/certs/service-cert.pem'), // Certificate của server
    ca: [fs.readFileSync('/etc/certs/internal-ca.pem')],  // Root CA nội bộ dùng để ký chứng chỉ cho các client microservices

    // YÊU CẦU BẮT BUỘC: Client phải trình chứng chỉ hợp lệ do internal CA cấp
    requestCert: true,
    rejectUnauthorized: true
  };

  app.get('/api/internal/orders', (req, res) => {
    // Trích xuất danh tính client từ chứng chỉ (SPIFFE ID hoặc Subject CN)
    const clientCert = (req.socket as any).getPeerCertificate();
    const clientSubject = clientCert.subject.CN;
    console.log(`Authenticated peer microservice: ${clientSubject}`);

    // Zero Trust: Ngay cả khi trong mạng nội bộ, vẫn xác thực danh tính từng request
    if (clientSubject !== 'payment-service.prod') {
      return res.status(403).json({ error: 'Zero Trust: Client service not authorized' });
    }

    res.json({ message: 'Order data accessed via authenticated mTLS channel' });
  });

  return https.createServer(options, app);
}

import { Request, Response } from 'express';
import crypto from 'crypto';

export class SessionSecurityManager {
  // Phòng chống Session Fixation: LUÔN HỦY VÀ TẠO MỚI Session ID ngay khi Authentication thành công
  static async onLoginSuccess(req: Request, res: Response, userId: string) {
    // 1. Huỷ session cũ được cấp khi còn là anonymous user
    await new Promise<void>((resolve, reject) => {
      req.session.regenerate((err) => (err ? reject(err) : resolve()));
    });

    // 2. Tính toán Device Fingerprint hiện tại để gán vào session
    const currentFingerprint = this.computeDeviceFingerprint(req);

    // 3. Khởi tạo session mới với định danh user và fingerprint
    req.session.userId = userId;
    req.session.deviceFingerprint = currentFingerprint;
    req.session.createdAt = Date.now();
  }

  // Phòng chống Session Hijacking: Kiểm tra tính bất biến của Device Context ở mỗi request
  static validateSessionIntegrity(req: Request): boolean {
    if (!req.session?.userId) return false;

    const currentFingerprint = this.computeDeviceFingerprint(req);
    if (req.session.deviceFingerprint !== currentFingerprint) {
      console.warn(`Phát hiện Session Hijacking nghi vấn trên user ${req.session.userId}`);
      // Hủy session ngay lập tức và ép người dùng xác thực lại
      req.session.destroy(() => {});
      return false;
    }

    return true;
  }

  private static computeDeviceFingerprint(req: Request): string {
    const userAgent = req.headers['user-agent'] || '';
    const acceptLanguage = req.headers['accept-language'] || '';
    return crypto.createHash('sha256').update(`${userAgent}-${acceptLanguage}`).digest('hex');
  }
}

import crypto from 'crypto';

export class PaymentCryptoService {
  // 1. Tạo Digital Signature (Chữ ký số): Ký bằng Private Key của Merchant
  static signPaymentPayload(payload: object, privateKeyPem: string): string {
    const dataString = JSON.stringify(payload);
    const sign = crypto.createSign('SHA256');
    sign.update(dataString);
    sign.end();

    // Chữ ký đảm bảo: Tính toàn vẹn (Integrity) và Chống chối bỏ (Non-repudiation)
    return sign.sign(privateKeyPem, 'base64');
  }

  // 2. Xác thực Digital Signature: Cổng thanh toán dùng Public Key của Merchant để kiểm tra
  static verifyPaymentSignature(payload: object, signatureBase64: string, publicKeyPem: string): boolean {
    const dataString = JSON.stringify(payload);
    const verify = crypto.createVerify('SHA256');
    verify.update(dataString);
    verify.end();

    return verify.verify(publicKeyPem, signatureBase64, 'base64');
  }
}

import crypto from 'crypto';
import Redis from 'ioredis';
import { Request, Response, NextFunction } from 'express';

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

export const verifySignedRequest = async (req: Request, res: Response, next: NextFunction) => {
  const signature = req.headers['x-signature'] as string;
  const timestamp = parseInt(req.headers['x-timestamp'] as string, 10);
  const nonce = req.headers['x-nonce'] as string;

  if (!signature || !timestamp || !nonce) {
    return res.status(400).json({ error: 'Thiếu headers xác thực chữ ký (Signature, Timestamp, Nonce)' });
  }

  // 1. Kiểm tra Timestamp: Chặn các request quá cũ hoặc đến từ tương lai quá xa (cửa sổ 5 phút)
  const now = Date.now();
  const WINDOW_MS = 5 * 60 * 1000;
  if (Math.abs(now - timestamp) > WINDOW_MS) {
    return res.status(400).json({ error: 'Request đã hết hạn hoặc lệch đồng hồ quá 5 phút' });
  }

  // 2. Kiểm tra Nonce (Number Used Once) trong Redis để phát hiện Replay
  const nonceKey = `nonce:${nonce}`;
  const isSet = await redis.set(nonceKey, '1', 'PX', WINDOW_MS, 'NX');
  if (!isSet) {
    // Nonce đã tồn tại trong Redis -> Đây là cuộc tấn công Replay Attack!
    return res.status(403).json({ error: 'Phát hiện Replay Attack: Nonce đã được sử dụng trước đó' });
  }

  // 3. Xác thực HMAC Signature trên toàn bộ body + headers
  const secretKey = process.env.API_PARTNER_SECRET!;
  const payloadToSign = `${req.method}|${req.originalUrl}|${timestamp}|${nonce}|${JSON.stringify(req.body)}`;
  const expectedSignature = crypto.createHmac('sha256', secretKey).update(payloadToSign).digest('hex');

  if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature))) {
    return res.status(401).json({ error: 'Chữ ký không hợp lệ' });
  }

  next();
};

import crypto from 'crypto';

export class SecurityComparator {
  // ❌ NGUY HIỂM CHẾT NGƯỜI: Toán tử '===' hoặc '==' tối ưu bằng cách return false ngay ở ký tự sai đầu tiên
  // Kẻ tấn công có thể đo thời gian phản hồi bằng microsecond để đoán từng ký tự một (Timing Attack)
  static vulnerableCompare(userApiKey: string, secretApiKey: string): boolean {
    return userApiKey === secretApiKey;
  }

  // ✅ AN TOÀN TUYỆT ĐỐI: Constant-Time Comparison (Thời gian thực thi luôn bằng nhau bất kể chuỗi giống hay khác)
  static secureCompare(userApiKey: string, secretApiKey: string): boolean {
    const userBuf = Buffer.from(userApiKey, 'utf8');
    const secretBuf = Buffer.from(secretApiKey, 'utf8');

    // 1. Nếu độ dài khác nhau, vẫn băm HMAC để giữ thời gian thực thi đồng nhất trước khi reject
    if (userBuf.length !== secretBuf.length) {
      // Chạy một phép toán giả để chống rò rỉ độ dài chuỗi qua timing
      crypto.timingSafeEqual(secretBuf, secretBuf);
      return false;
    }

    // 2. crypto.timingSafeEqual duyệt qua toàn bộ mảng byte bằng phép toán XOR (b1 ^ b2) không có early return
    return crypto.timingSafeEqual(userBuf, secretBuf);
  }
}

import { XMLParser } from 'fast-xml-parser';

// 1. Phòng chống XML External Entity (XXE) Attack
// Payload độc hại: <!DOCTYPE foo [ <!ENTITY xxe SYSTEM "file:///etc/passwd"> ]>
export class SecureXmlProcessor {
  private static parser = new XMLParser({
    // VÔ HIỆU HÓA TOÀN BỘ các tính năng DTD và Entity Expansion nguy hiểm
    allowBooleanAttributes: false,
    processEntities: false,  // Không xử lý entity tham chiếu ra ngoài
    htmlEntities: false,
    ignoreAttributes: false
  });

  static parseXmlSafely(rawXmlString: string) {
    // Kiểm tra sơ bộ chặn các từ khóa DTD nguy hiểm
    if (rawXmlString.includes('<!DOCTYPE') || rawXmlString.includes('<!ENTITY')) {
      throw new Error('Từ chối XML chứa DOCTYPE hoặc DTD Entity (Nguy cơ XXE)');
    }

    return this.parser.parse(rawXmlString);
  }
}

// 2. Phòng chống Insecure Deserialization
export class SerializationSecurity {
  // ❌ NGUY HIỂM: Dùng eval() hoặc node-serialize / python pickle trên untrusted data dẫn tới RCE
  // ✅ AN TOÀN: Chỉ dùng JSON schema chặt chẽ (JSON.parse không chứa hàm thực thi)
  static safeDeserialize<T>(jsonStr: string): T {
    const parsed = JSON.parse(jsonStr);
    // Luôn validate lại cấu trúc object bằng schema (Zod / Joi) sau khi parse
    return parsed as T;
  }
}

import https from 'https';
import crypto from 'crypto';
import tls from 'tls';

// Triển khai Public Key Pinning (SPKI Pinning) cho Client Connection
export class SecurePinnedHttpClient {
  // Danh sách SHA-256 hash của Subject Public Key Info (SPKI)
  // LUÔN LUÔN cấu hình ít nhất 1 mã Pin chính và 1 mã Pin dự phòng (Backup Pin)!
  private static readonly PINNED_SPKI_HASHES = [
    '47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFU=', // Current Production Public Key
    'd6qzRu9zOECb90Uez27xWltNsj0eQ8jodZF97A6vUUM='  // Backup Key (Lưu an toàn trong két sắt)
  ];

  static verifyPeerCertificate(tlsSocket: tls.TLSSocket): boolean {
    const cert = tlsSocket.getPeerCertificate();
    if (!cert || !cert.pubkey) return false;

    // Tính toán SHA-256 hash của Subject Public Key Info (SPKI)
    const publicKeyHash = crypto.createHash('sha256').update(cert.pubkey).digest('base64');

    const isMatch = this.PINNED_SPKI_HASHES.includes(publicKeyHash);
    if (!isMatch) {
      console.error('SSL PINNING VIOLATION: Phát hiện máy chủ lạ hoặc tấn công Man-in-the-Middle!');
      tlsSocket.destroy(new Error('SSL Pinning validation failed'));
      return false;
    }

    return true;
  }
}
